 ══════════════════════════════════════════════════\n% ROW B: Hidden Warming + Baseline Comparison + Implications\n% ══════════════════════════════════════════════════\n\n% Col 1: Pre-Industrial Baseline Matters (row11 to row16)\n\\posterbox[warncard, title={Pre-Industrial Baseline Matters}\n]{name=keyfinding, column=1, between=row11 and row16}{\n  \\fontsize{32}{42}\\selectfont\n  \\begin{itemize}[itemsep=10pt]\n    \\item IPCC uses 1850--1900 as ``pre-industrial'' baseline\n    \\item This period was \\textbf{already 0.5\\,°C above} the true 1700--1790 baseline\n    \\item Instrumental record systematically underestimates total warming\n  \\end{itemize}\n  \\vspace{4mm}\n  \\colorbox{warnred!20}{\\parbox{0.92\\linewidth}{%\n    \\centering\\vspace{6pt}%\n    {\\fontsize{36}{44}\\selectfont\\bfseries\\color{warnred}\n    $\\sim$0.5\\,°C of warming occurred}\\\\[2pt]\n    {\\fontsize{36}{44}\\selectfont\\bfseries\\color{warnred}\n    before the instrumental era begins}%\n    \\vspace{6pt}%\n  }}\n}\n\n% Col 2: Baseline Comparison Figure (row11 to row16)\n\\posterbox[warmcard, title={Baseline Choice Determines the Outcome}\n]{name=baseline, column=2, between=row11 and row16}{\n  \\posterfig{0.95}{figures/baseline_comparison.png}{Side-by-side comparison of total warming under the IPCC baseline vs.\\ the true pre-industrial baseline.}\n  \\vspace{2mm}\n  \\fontsize{30}{40}\\selectfont\n  \\renewcommand{\\arraystretch}{1.6}\n  \\centering\n  \\begin{tabular}{>{\\raggedright\\arraybackslash}p{0.42\\linewidth}>{\\centering\\arraybackslash}p{0.22\\linewidth}>{\\centering\\arraybackslash}p{0.22\\linewidth}}\n    \\rowcolor{primary!15}\n    \\textbf{Baseline} & \\textbf{Warming} & \\textbf{Exceeds 1.5?} \\\\\n    \\rowcolor{bluebg}\n    1850--1900 (IPCC) & $\\sim$1.2\\,°C & No \\\\\n    \\rowcolor{highlightbg}\n    1700--1790 (true) & $\\sim$1.7\\,°C & \\textbf{Yes} \\\\\n  \\end{tabular}\n}\n\n% Col 3: Policy Implications (row11 to row16)\n\\posterbox[darkcard, title={Policy \\& Climate Target Implications}\n]{name=implications, column=3, between=row11 and row16}{\n  \\fontsize{32}{42}\\selectfont\n  \\begin{itemize}[itemsep=10pt]\n    \\item Paris 1.5\\,°C target framed vs.\\ ``pre-industrial'' but IPCC uses 1850--1900\n    \\item Remaining carbon budget for 1.5\\,°C is \\textbf{effectively zero}\n    \\item 2.0\\,°C guardrail is closer: only $\\sim$0.3\\,°C of headroom, not $\\sim$0.8\\,°C\n    \\item Urgent need for transparent baseline communication\n  \\end{itemize}\n  \\vspace{4mm}\n  \\colorbox{accent!20}{\\parbox{0.92\\linewidth}{%\n    \\centering\\vspace{6pt}%\n    {\\fontsize{30}{38}\\selectfont\\bfseries\\color{accent}\n    1.5\\,°C is not a future threshold ---}\\\\[2pt]\n    {\\fontsize{30}{38}\\selectfont\\bfseries\\color{accent}\n    it has already been crossed}%\n    \\vspace{6pt}%\n  }}\n}\n\n% ══════════════════════════════════════════════════\n% ROW C: Methods + Milestones + Takeaways\n% ══════════════════════════════════════════════════\n\n% Col 1: Data & Methods (row16 to row20)\n\\posterbox[bluecard, title={Data \\& Methods}\n]{name=methods, column=1, between=row16 and row20}{\n  \\fontsize{30}{40}\\selectfont\n  \\begin{itemize}[itemsep=8pt]\n    \\item \\textbf{Specimens:} Caribbean reef environments, 33--91\\,m depth\n    \\item \\textbf{Measurement:} Sr/Ca via ICP-OES\n    \\item \\textbf{Calibration:} Co-located instrumental SST (1960+), $r^{2} > 0.9$\n    \\item \\textbf{Validation:} Excellent agreement with HadCRUT5 \\& NOAA ERSSTv5 during overlap\n    \\item \\textbf{Divergence:} Before $\\sim$1850, precisely where hidden warming resides\n  \\end{itemize}\n}\n\n% Col 2: Timeline Milestones (row16 to row20)\n\\posterbox[darkcard, title={Key Milestones in the Reconstruction}\n]{name=milestones, column=2, between=row16 and row20}{\n  \\fontsize{30}{40}\\selectfont\n  \\renewcommand{\\arraystretch}{1.5}\n  \\centering\n  \\begin{tabular}{>{\\raggedright\\arraybackslash}p{0.25\\linewidth}>{\\raggedright\\arraybackslash}p{0.65\\linewidth}}\n    \\rowcolor{primary!15}\n    \\textbf{Period} & \\textbf{Observation} \\\\\n    \\rowcolor{bluebg}\n    1700--1790 & Stable pre-industrial temperatures (true baseline) \\\\\n    \\rowcolor{darkbg}\n    1790--1850 & Detectable warming onset from early industrialisation \\\\\n    \\rowcolor{bluebg}\n    1850--1900 & Already $\\sim$0.5\\,°C above true baseline \\\\\n    \\rowcolor{darkbg}\n    1900--1960 & Gradual warming; volcanic cooling episodes visible \\\\\n    \\rowcolor{bluebg}\n    1960--2000 & Acceleration; proxy \\& instrumental records converge \\\\\n    \\rowcolor{highlightbg}\n    2000--now & \\textbf{Warming exceeds 1.5\\,°C} (true pre-industrial) \\\\\n  \\end{tabular}\n}\n\n% Col 3: Key Takeaways (row16 to row20)\n\\posterbox[highlightcard, title={Key Takeaways}\n]{name=takeaways, column=3, between=row16 and row20}{\n  \\fontsize{32}{42}\\selectfont\n  \\begin{enumerate}[itemsep=12pt]\n    \\item Sclerosponge proxies extend the temperature record back to $\\sim$1700 CE\n    \\item The 1850--1900 IPCC baseline omits $\\sim$0.5\\,°C of early anthropogenic warming\n    \\item Global warming has \\textbf{already exceeded 1.5\\,°C} relative to a true pre-industrial baseline\n    \\item Remaining carbon budgets are smaller than currently estimated\n  \\end{enumerate}\n  \\vspace{4mm}\n  \\centering\n  \\colorbox{white}{\\parbox{0.88\\linewidth}{%\n    \\centering\\vspace{6pt}%\n    {\\fontsize{26}{32}\\selectfont\\color{primary}\n   McCulloch et al.\\ (2024).\\ \\textit{Nature Climate Change}}\\\\[3pt]\n    {\\fontsize{22}{28}\\selectfont\\color{textgray}\n    doi:10.1038/s41558-024-01990-8}%\n    \\vspace{6pt}%\n  }}\n}\n\n\\end{tcbposter}\n\\end{document}\n", "numLines": 308, "startLine": 1, "totalLines": 308}}

