\documentclass{article}
\usepackage[paperwidth=841mm,paperheight=1189mm,margin=0mm]{geometry}
\usepackage{tcolorbox}
\tcbuselibrary{poster,skins,fitting}
\usepackage{graphicx}
\usepackage{amsmath,amssymb}
\usepackage{enumitem}
\usepackage[table]{xcolor}
\usepackage{lmodern}
\usepackage[T1]{fontenc}
\pagestyle{empty}

% ══ Color Theme: Ocean-to-Warming (Climate Science) ══
\definecolor{primary}{HTML}{0A2647}       % Deep ocean navy
\definecolor{secondary}{HTML}{144272}     % Medium blue
\definecolor{accent}{HTML}{DC4A1A}        % Warming amber-red
\definecolor{bgposter}{HTML}{EFF6FF}      % Light blue poster background
\definecolor{bluebg}{HTML}{F0F7FF}        % Cool card tint
\definecolor{warmbg}{HTML}{FFF7ED}        % Warm card tint
\definecolor{darkbg}{HTML}{F0F4F8}        % Neutral card tint
\definecolor{highlightbg}{HTML}{FEF2F2}   % Red warning tint
\definecolor{bluetitlebg}{HTML}{DBEAFE}   % Blue title bar tint
\definecolor{warmtitlebg}{HTML}{FED7AA}   % Warm title bar tint
\definecolor{darktitlebg}{HTML}{E2E8F0}   % Neutral title bar tint
\definecolor{textdark}{HTML}{111827}
\definecolor{textgray}{HTML}{4B5563}
\definecolor{stathighlight}{HTML}{FEE2E2}
\definecolor{warnred}{HTML}{DC2626}

\pagecolor{bgposter}
\color{textdark}

% ══ List styling ══
\setlist[itemize]{leftmargin=24pt, itemsep=8pt, parsep=2pt, topsep=2pt,
  label={\color{secondary}$\blacktriangleright$}}
\setlist[enumerate]{leftmargin=24pt, itemsep=8pt, parsep=2pt, topsep=2pt,
  label={\color{primary}\bfseries\arabic*.}}

% ══ Figure+caption macro ══
\newcommand{\posterfig}[3]{%
  \centering\includegraphics[width=#1\linewidth]{#2}\\[3mm]
  {\fontsize{24}{30}\selectfont\color{textgray}\textit{#3}}\vspace{2mm}%
}

% ══ Card styles ══
\tcbset{
  bluecard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=bluebg,
    borderline west={5pt}{0pt}{secondary},
    left=16pt, right=14pt, top=4pt, bottom=4pt,
    fonttitle=\fontsize{38}{46}\selectfont\bfseries\color{secondary},
    coltitle=secondary, colbacktitle=bluetitlebg,
    toptitle=6pt, bottomtitle=6pt,
    titlerule=2pt, titlerule style={secondary!50},
    valign=top, drop shadow={opacity=0.18},
  },
  warmcard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=warmbg,
    borderline west={5pt}{0pt}{accent},
    left=16pt, right=14pt, top=4pt, bottom=4pt,
    fonttitle=\fontsize{38}{46}\selectfont\bfseries\color{accent},
    coltitle=accent, colbacktitle=warmtitlebg,
    toptitle=6pt, bottomtitle=6pt,
    titlerule=2pt, titlerule style={accent!50},
    valign=top, drop shadow={opacity=0.18},
  },
  darkcard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=darkbg,
    borderline west={5pt}{0pt}{primary},
    left=16pt, right=14pt, top=4pt, bottom=4pt,
    fonttitle=\fontsize{38}{46}\selectfont\bfseries\color{primary},
    coltitle=primary, colbacktitle=darktitlebg,
    toptitle=6pt, bottomtitle=6pt,
    titlerule=2pt, titlerule style={primary!50},
    valign=top, drop shadow={opacity=0.18},
  },
  highlightcard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=primary!15!white,
    borderline west={6pt}{0pt}{primary},
    left=16pt, right=14pt, top=4pt, bottom=4pt,
    fonttitle=\fontsize{38}{46}\selectfont\bfseries\color{white},
    coltitle=white, colbacktitle=primary,
    toptitle=6pt, bottomtitle=6pt,
    valign=top, drop shadow={opacity=0.22},
  },
  warncard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=highlightbg,
    borderline west={6pt}{0pt}{warnred},
    left=16pt, right=14pt, top=4pt, bottom=4pt,
    fonttitle=\fontsize{38}{46}\selectfont\bfseries\color{warnred},
    coltitle=warnred, colbacktitle=stathighlight,
    toptitle=6pt, bottomtitle=6pt,
    titlerule=2pt, titlerule style={warnred!50},
    valign=top, drop shadow={opacity=0.18},
  },
}

\begin{document}
\begin{tcbposter}[
  coverage={spread},
  poster={columns=3, rows=20, spacing=0mm},
]

% ══════════════════════════════════════════════════
% TITLE BAR (span=3, rows top to row3)
% ══════════════════════════════════════════════════
\posterbox[
  enhanced, colback=primary, colframe=primary, colupper=white,
  arc=0pt, boxrule=0pt,
  left=40pt, right=40pt, top=14pt, bottom=10pt,
  halign=center, valign=center,
  drop shadow={opacity=0.3}
]{name=title, column=1, span=3, between=top and row3}{
  {\fontsize{76}{92}\selectfont\bfseries 300 Years of Sclerosponge Thermometry}\\[10pt]
  {\fontsize{70}{86}\selectfont\bfseries Shows Global Warming Has Exceeded 1.5\,°C}\\[14pt]
  {\fontsize{34}{42}\selectfont Malcolm D. McCulloch, Paola F. Rachello-Dolmen, et al.}\\[6pt]
  {\fontsize{28}{36}\selectfont\color{white!70} University of Western Australia $\cdot$ Curtin University $\cdot$ ETH Z\"urich}\\[4pt]
  {\fontsize{26}{32}\selectfont\color{accent} Nature Climate Change (2024) $\cdot$ AGU Fall Meeting 2024}
}

% ══════════════════════════════════════════════════
% STATS BANNER (span=3, rows row3 to row5)
% ══════════════════════════════════════════════════
\posterbox[
  enhanced, colback=primary!12!white, boxrule=0pt, arc=0pt,
  left=12pt, right=12pt, top=6pt, bottom=6pt,
  valign=center, borderline south={3pt}{0pt}{primary!30},
]{name=stats, column=1, span=3, between=row3 and row5}{
  \centering
  % Stat 1: Hidden warming
  \begin{minipage}[c]{0.3\linewidth}\centering
    \fcolorbox{accent!50}{stathighlight}{\parbox{0.88\linewidth}{%
      \centering\vspace{6pt}%
      {\fontsize{64}{78}\selectfont\bfseries\color{accent} +0.5\,°C}\\[4pt]
      {\fontsize{24}{30}\selectfont\color{textdark} Hidden pre-industrial warming}\vspace{6pt}%
    }}
  \end{minipage}\hfill
  % Stat 2: Total warming
  \begin{minipage}[c]{0.3\linewidth}\centering
    \fcolorbox{warnred!50}{stathighlight}{\parbox{0.88\linewidth}{%
      \centering\vspace{6pt}%
      {\fontsize{64}{78}\selectfont\bfseries\color{warnred} $>$1.5\,°C}\\[4pt]
      {\fontsize{24}{30}\selectfont\color{textdark} Total warming from true baseline}\vspace{6pt}%
    }}
  \end{minipage}\hfill
  % Stat 3: Record length
  \begin{minipage}[c]{0.3\linewidth}\centering
    \fcolorbox{secondary!50}{bluetitlebg}{\parbox{0.88\linewidth}{%
      \centering\vspace{6pt}%
      {\fontsize{64}{78}\selectfont\bfseries\color{primary} 300\,yr}\\[4pt]
      {\fontsize{24}{30}\selectfont\color{textdark} Continuous ocean proxy record}\vspace{6pt}%
    }}
  \end{minipage}
}

% ══════════════════════════════════════════════════
% ROW A: Why Sclerosponges + HERO Timeline
% ══════════════════════════════════════════════════

% Col 1: Why Sclerosponges? (row5 to row11)
\posterbox[bluecard, title={Why Sclerosponges?}
]{name=background, column=1, between=row5 and row11}{
  \fontsize{32}{42}\selectfont
  \begin{itemize}[itemsep=10pt]
    \item Long-lived marine organisms with centuries of continuous growth
    \item Sr/Ca ratios track sea-surface temperature with annual resolution
    \item Tropical ocean sensitivity: Caribbean sites capture large-scale SST variability
    \item Independent of instrumental networks that begin only $\sim$1850
  \end{itemize}
  \vspace{4mm}
  \posterfig{0.92}{figures/sclerosponge_diagram.png}{Cross-section: centuries of annual growth bands recording ocean temperature.}
}

% Col 2+3: 300-Year Temperature Timeline (HERO) (row5 to row11)
\posterbox[warmcard, title={300-Year Temperature Reconstruction}
]{name=timeline, column=2, span=2, between=row5 and row11}{
  \posterfig{0.98}{figures/temperature_timeline.png}{Reconstructed temperature anomaly from sclerosponge Sr/Ca proxies (blue) vs.\ IPCC convention (dashed). The 1.5\,°C Paris threshold is exceeded by the early 2020s.}
}

% ══════════════════════════════════════════════════
% ROW B: Hidden Warming + Baseline Comparison + Implications
% ══════════════════════════════════════════════════

% Col 1: Pre-Industrial Baseline Matters (row11 to row16)
\posterbox[warncard, title={Pre-Industrial Baseline Matters}
]{name=keyfinding, column=1, between=row11 and row16}{
  \fontsize{32}{42}\selectfont
  \begin{itemize}[itemsep=10pt]
    \item IPCC uses 1850--1900 as ``pre-industrial'' baseline
    \item This period was \textbf{already 0.5\,°C above} the true 1700--1790 baseline
    \item Instrumental record systematically underestimates total warming
  \end{itemize}
  \vspace{4mm}
  \colorbox{warnred!20}{\parbox{0.92\linewidth}{%
    \centering\vspace{6pt}%
    {\fontsize{36}{44}\selectfont\bfseries\color{warnred}
    $\sim$0.5\,°C of warming occurred}\\[2pt]
    {\fontsize{36}{44}\selectfont\bfseries\color{warnred}
    before the instrumental era begins}%
    \vspace{6pt}%
  }}
}

