229	    \item 2.0\,°C guardrail is closer: only $\sim$0.3\,°C of headroom, not $\sim$0.8\,°C
230	    \item Urgent need for transparent baseline communication
231	  \end{itemize}
232	  \vspace{4mm}
233	  \colorbox{accent!20}{\parbox{0.92\linewidth}{%
234	    \centering\vspace{6pt}%
235	    {\fontsize{30}{38}\selectfont\bfseries\color{accent}
236	    1.5\,°C is not a future threshold ---}\\[2pt]
237	    {\fontsize{30}{38}\selectfont\bfseries\color{accent}
238	    it has already been crossed}%
239	    \vspace{6pt}%
240	  }}
241	}
