248	\posterbox[bluecard, title={Data \& Methods}
249	]{name=methods, column=1, between=row16 and row20}{
250	  \fontsize{30}{40}\selectfont
251	  \begin{itemize}[itemsep=8pt]
252	    \item \textbf{Specimens:} Caribbean reef environments, 33--91\,m depth
253	    \item \textbf{Measurement:} Sr/Ca via ICP-OES
254	    \item \textbf{Calibration:} Co-located instrumental SST (1960+), $r^{2} > 0.9$
255	    \item \textbf{Validation:} Excellent agreement with HadCRUT5 \& NOAA ERSSTv5 during overlap
256	    \item \textbf{Divergence:} Before $\sim$1850, precisely where hidden warming resides
257	  \end{itemize}
258	}
259	
