261	\posterbox[darkcard, title={Key Milestones in the Reconstruction}
262	]{name=milestones, column=2, between=row16 and row20}{
263	  \fontsize{30}{40}\selectfont
264	  \renewcommand{\arraystretch}{1.5}
265	  \centering
