267	    \rowcolor{primary!15}
268	    \textbf{Period} & \textbf{Observation} \\
269	    \rowcolor{bluebg}
270	    1700--1790 & Stable pre-industrial temperatures (true baseline) \\
271	    \rowcolor{darkbg}
272	    1790--1850 & Detectable warming onset from early industrialisation \\
273	    \rowcolor{bluebg}
274	    1850--1900 & Already $\sim$0.5\,°C above true baseline \\
275	    \rowcolor{darkbg}
276	    1900--1960 & Gradual warming; volcanic cooling episodes visible \\
277	    \rowcolor{bluebg}
278	    1960--2000 & Acceleration; proxy \& instrumental records converge \\
279	    \rowcolor{highlightbg}
280	    2000--now & \textbf{Warming exceeds 1.5\,°C} (true pre-industrial) \\
281	  \end{tabular}
282	}
283	
284	% Col 3: Key Takeaways (row16 to row20)
285	\posterbox[highlightcard, title={Key Takeaways}
286	]{name=takeaways, column=3, between=row16 and row20}{
287	  \fontsize{32}{42}\selectfont
288	  \begin{enumerate}[itemsep=12pt]
289	    \item Sclerosponge proxies extend the temperature record back to $\sim$1700 CE
290	    \item The 1850--1900 IPCC baseline omits $\sim$0.5\,°C of early anthropogenic warming
291	    \item Global warming has \textbf{already exceeded 1.5\,°C} relative to a true pre-industrial baseline
292	    \item Remaining carbon budgets are smaller than currently estimated
293	  \end{enumerate}
